@extends('layouts.app')
@section('title', '在线地图')
@section('content')
<div class="space-y-5"><section class="card border-0 bg-gradient-to-br from-emerald-600 to-cyan-700 p-5 text-white"><h1 class="text-2xl font-bold">服务器在线地图</h1><p class="mt-1 text-emerald-50">原生 Dynmap 地图 · 按真实瓦片坐标渲染</p></section><section class="card overflow-hidden"><div class="flex flex-wrap items-center gap-3 border-b p-4"><select id="world" class="rounded border p-2"></select><select id="map" class="rounded border p-2"></select><button id="reset" class="rounded bg-primary-50 px-3 py-2 text-primary-700">居中</button><span id="hint" class="text-sm text-slate-500"></span></div><div id="view" class="relative h-[70vh] min-h-[520px] overflow-hidden bg-slate-900 touch-none"><div id="layer" class="absolute" style="transform-origin:0 0"></div></div></section></div>
<style>.dyn-tile{position:absolute;width:128px;height:128px;max-width:none;display:block}</style>
<script>
(()=>{const ws=document.querySelector('#world'),ms=document.querySelector('#map'),view=document.querySelector('#view'),layer=document.querySelector('#layer'),hint=document.querySelector('#hint');let worlds=[],items=[],state={x:0,y:0,s:1},drag=null;const enc=encodeURIComponent;function move(){layer.style.transform=`translate(${state.x}px,${state.y}px) scale(${state.s})`}function fit(){if(!items.length)return;const xs=items.map(v=>v.x),ys=items.map(v=>v.y),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),width=(maxx-minx+1)*128,height=(maxy-miny+1)*128;state.s=Math.max(.1,Math.min(1,view.clientWidth/width,view.clientHeight/height));state.x=(view.clientWidth-width*state.s)/2-minx*128*state.s;state.y=(view.clientHeight-height*state.s)/2-miny*128*state.s;move()}async function draw(){const w=worlds[+ws.value],map=w.maps[+ms.value],name=map.prefix||map.name;hint.textContent='加载地图…';const r=await fetch(`/map/tiles-manifest/${enc(w.name)}/${enc(name)}?_=${Date.now()}`),d=await r.json();items=(d.tiles||[]).map((file,i)=>{const a=file.match(/(-?\d+)_(-?\d+)\.(?:png|jpe?g|webp)$/i);return {file,x:a?+a[1]:i%20,y:a?+a[2]:Math.floor(i/20)}});layer.innerHTML='';for(const t of items){const img=document.createElement('img');img.className='dyn-tile';img.style.left=(t.x*128)+'px';img.style.top=(t.y*128)+'px';img.src=`/map/tile-file?world=${enc(w.name)}&map=${enc(name)}&path=${enc(t.file)}`;layer.appendChild(img)}fit();hint.textContent=`${w.name} / ${name} · ${items.length} 块瓦片`}function setMaps(){const w=worlds[+ws.value];ms.innerHTML=w.maps.map((m,i)=>`<option value="${i}">${m.title||m.name||m.prefix}</option>`).join('');draw()}async function start(){const r=await fetch('/map/data?_='+Date.now()),d=await r.json();worlds=(d.data?.worlds||[]).filter(w=>w.name!=='faces');if(!worlds.length)throw Error('没有可用世界');ws.innerHTML=worlds.map((w,i)=>`<option value="${i}">${w.title||w.name}</option>`).join('');setMaps()}ws.onchange=setMaps;ms.onchange=draw;document.querySelector('#reset').onclick=fit;view.addEventListener('pointerdown',e=>{drag={px:e.clientX,py:e.clientY,x:state.x,y:state.y};view.setPointerCapture(e.pointerId)});view.addEventListener('pointermove',e=>{if(!drag)return;state.x=drag.x+e.clientX-drag.px;state.y=drag.y+e.clientY-drag.py;move()});view.addEventListener('pointerup',()=>drag=null);view.addEventListener('wheel',e=>{e.preventDefault();const b=state.s,n=Math.max(.1,Math.min(3,b*(e.deltaY<0?1.15:.87))),box=view.getBoundingClientRect(),mx=e.clientX-box.left,my=e.clientY-box.top;state.x=mx-(mx-state.x)*n/b;state.y=my-(my-state.y)*n/b;state.s=n;move()},{passive:false});start().catch(e=>hint.textContent=e.message)})();
</script>
@endsection